        { childId: "ipt_corpRegNo2", fn: function () { return String(String(dma_detailData.get("corpRegNo")).substring(6, 13)); } },
        { childId: "btn_DownloadFile", fn: function () { return String(dlt_attachList01.getCellData(0, "attachFileNm")); } },
        { childId: "btn_DownloadFile_2", fn: function () { return String(dlt_attachList02.getCellData(0, "attachFileNm")); } },
        { childId: "btn_DownloadFile_3", fn: function () { return String(dlt_attachList02.getCellData(1, "attachFileNm")); } },
        { childId: "btn_DownloadFile_4", fn: function () { return String(dlt_attachList02.getCellData(2, "attachFileNm")); } },
        { childId: "btn_DownloadFile_5", fn: function () { return String(dlt_attachList13.getCellData(0, "attachFileNm")); } },
        { childId: "btn_DownloadFile_6", fn: function () { return String(dlt_attachList13.getCellData(1, "attachFileNm")); } },
        { childId: "btn_DownloadFile_7", fn: function () { return String(dlt_attachList13.getCellData(2, "attachFileNm")); } },
        { childId: "__rb0", fn: function () { return String(dma_detailData.get("rsltNotiDd")); } },
        { childId: "__rb1", fn: function () { return " " + String(dma_detailData.get("rsltNotiDd")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

