/**
 * @method
 * @name checkBzRegNo
 * @description check Bz Reg No 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkBzRegNo = async function () {
    const bzRegNo1 = $c.util.getComponent('ipt_bzRegNo1').getValue();
    const bzRegNo2 = $c.util.getComponent('ipt_bzRegNo2').getValue();
    const bzRegNo3 = $c.util.getComponent('ipt_bzRegNo3').getValue();
    const bzRegNo = bzRegNo1 + bzRegNo2 + bzRegNo3;
    if (bzRegNo.length > 0) {
        let subMode = 0;
        subMode += parseInt(bzRegNo.substring(0, 1));
        subMode += parseInt(bzRegNo.substring(1, 2)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(2, 3)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(3, 4)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(4, 5)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(5, 6)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(6, 7)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(7, 8)) * 3 % 10;
        subMode += Math.floor(parseInt(bzRegNo.substring(8, 9)) * 5 / 10);
        subMode += parseInt(bzRegNo.substring(8, 9)) * 5 % 10;
        subMode += parseInt(bzRegNo.substring(9, 10));
        if (subMode % 10 !== 0) {
            await $c.win.alert("사업자등록번호가 잘못되었습니다.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @param {*} standardByte standardByte
 * @param {String} byteCntId byteCntId
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj, standardByte, byteCntId) {

    // 기준바이트 수
    // var standardByte = 100;

    const contnByte = scwin.getByte(_obj);

    const byteCntObj = $c.util.getComponent(byteCntId);
    byteCntObj.innerText = "(" + (contnByte) + "/"+standardByte+" byte)";

    if(contnByte > standardByte){
        await $c.win.alert( (contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();

        // 초과한 문자열을 삭제
        _obj.setValue(scwin.calcContn(contnValue, standardByte));

        // 바이트수를 재계산
        await scwin.checkByte(_obj, standardByte, byteCntId);
    }
};

/**
 * @method
 * @name setPhoneValue
 * @description set Phone Value 처리
 * @param {*} _target _target
 * @param {*} _val _val
 * @param {*} _frmObj _frmObj
 * @returns {void}
 * @hidden N
 */
scwin.setPhoneValue = function (_target, _val, _frmObj) {

    let tmpVal;
    let currentVal = _val;
    let tmpIndex = 0;

    const frm = _frmObj;

    for(let i=3; i>=1;i--){
        tmpIndex = currentVal.lastIndexOf('-');
        tmpVal = currentVal.substring(tmpIndex+1, currentVal.length);

        frm[_target + i].value = tmpVal;

        currentVal = currentVal.substring(0, tmpIndex);
    }
};

