    else return _str;
};

/**
 * @method
 * @name isExceedMaxLen
 * @description is Exceed Max Len 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isExceedMaxLen = async function (_obj) {

    let retVal = false;
    const contn = _obj.value;

    // HTML의 maxLength 속성이 있으면 가져오고, 없으면 충분히 큰 값을 기본값으로 설정
    const maximum = _obj.getAttribute("maxlength") || _obj.maxLength;

    // 만약 maximum이 설정되지 않았거나 -1(기본값)이라면 체크를 건너뜁니다.
    if (!maximum || maximum <= 0) return false;

    let nbytes = 0;

    for (let i = 0; i < contn.length; i++) {
        const ch = contn.charAt(i);
        let inc = 0;

        // 1. 엔터값 처리 (크롬/IE 공통 표준화)
        if (ch === '\n') {
            inc = 1;
        }
        // 2. 한글 및 다국어 처리 (유니코드 기반)
        // 한글은 보통 2~3바이트지만, 기존 로직(2바이트)을 유지하기 위해 체크
        else if (encodeURI(ch).length > 4) {
            inc = 2;
        }
        // 3. 특수 기호 처리 (<, > 를 4바이트로 치려는 기존 로직 유지)
        else if (ch === '<' || ch === '>') {
            inc = 4;
        }
        // 4. 나머지 영문/숫자
        else {
            inc = 1;
        }

        nbytes += inc;

        if (nbytes > maximum) {
            await $c.win.alert("'" + (((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(_obj) || "입력") + "' 항목은 한글 " + Math.floor(maximum / 2) + "자, 영문 " + maximum + "자까지 가능합니다.");
            _obj.focus(); // focus 뒤에 () 추가
            retVal = true;
            break;
        }
    }

    return retVal;
};

/**
 * @method
 * @name chkNumber2
 * @description chk Number2 처리
 * @param {*} val val
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkNumber2 = async function (val) {

    if(event.keyCode ===8 ) return;      // backspace
    if(event.keyCode ===9 ) return;      // TAB
    if(event.keyCode ===13 ) return;     // ENTER
    if(event.keyCode ===33 ) return;     // PageUp
    if(event.keyCode ===34 ) return;     // PageDown
    if(event.keyCode ===35 ) return;     // EndKey
    if(event.keyCode ===36 ) return;     // HomeKey
    if(event.keyCode ===46 ) return;     // DeleteKey
    if($c.util.getKeyCode(event) >=37 && $c.util.getKeyCode(event) <= 40 ) return;  // CURSOR KEY
    if($c.util.getKeyCode(event) >=96 && $c.util.getKeyCode(event) <= 105 ) return;  // RIGHT NUMBER KEY

    if( ($c.util.getKeyCode(event)<48)||($c.util.getKeyCode(event)>57)){
        if(!scwin.isNumber(event.srcElement)){
            await $c.win.alert('숫자만 입력 가능합니다.');
            val.value = '';
            event.returnValue=false;
        }
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {

    const sTmpCntnt = new String(_obj.getValue()); // 내용 저장 변수

    let iCounts = 0; // 바이트 수 저장 변수

    for (let i = 0 ;i < sTmpCntnt.length; i++) {
        //  16 진수 변환
        const escapeChar = escape(sTmpCntnt.charAt(i))

        if (escapeChar === '%0A') { // enter 처리
            iCounts += 2;
        } else if (escapeChar.length > 4) { // 한글 2byte 처리
            iCounts += 2;
        } else  {
            iCounts++;
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {

    let rContn = "";
    let nbytes = 0; // 총 byte 수

    for (let i=0; i<_contn.length; i++) {
        const ch = _contn.charAt(i);

        let inc = 0; // 증가치 변수

        if (ch === '\n') { // enter 처리
            if (_contn.charAt(i-1) !== '\r') {
                inc = 1;
            }
        }else if (escape(ch).length > 4) {
            inc = 2;
        } else if (ch === '<' || ch === '>') {
            inc = 4;
        } else {
            inc = 1;
        }

        nbytes += inc;

        if (nbytes > _maximum) { // _maximum 넘어서면 break
            break;
        }

        rContn += ch; // ch 추가
    }

    return rContn;
};

/**
 * @method
 * @name isNumber
 * @description is Number 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function (_obj) {

    str = scwin.ignoreSpaces(_obj.value);
    for(i=0;i<str.length;i++){
        if (isNaN(str.substr(i,1)) === true){
            _obj.select();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name ignoreSpaces
 * @description ignore Spaces 처리
 * @param {*} _str _str
 * @returns {void}
 * @hidden N
 */
scwin.ignoreSpaces = function (_str) {

    return _str.replace(/\s/g, "");
};

